#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { fixSource } = require('./index');

const VERSION = '1.0.0';
const EXCLUDED = new Set(['node_modules', '.git', '.next', 'dist', 'build', 'out', 'coverage', '.turbo', '.cache']);
const EXTENSIONS = new Set(['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.html', '.vue', '.svelte']);

function help() { return `twcheck ${VERSION}\n\nFind and fix non-canonical Tailwind CSS classes.\n\nUsage:\n  twcheck <path> [options]\n\nOptions:\n  --diff       Preview line-by-line changes without writing\n  --fix        Apply all fixes\n  --check      Check mode; exit 1 when warnings are found\n  --json       Print machine-readable results\n  --css <file> Tailwind CSS entrypoint override\n  --help       Show this help\n  --version    Show the version\n` }

function parse(argv) { const o = { path: '.', diff: false, fix: false, check: false, json: false }; for (let i=0;i<argv.length;i++) { const a=argv[i]; if (a==='--help'||a==='-h') o.help=true; else if(a==='--version'||a==='-v') o.version=true; else if(a==='--diff') o.diff=true; else if(a==='--fix') o.fix=true; else if(a==='--check') o.check=true; else if(a==='--json') o.json=true; else if(a==='--css') o.css=argv[++i]; else if(!a.startsWith('-')) o.path=a; else throw new Error(`Unknown option: ${a}`); } return o; }

function ignoredByGitignore(file, root) { const gi = path.join(root, '.gitignore'); if (!fs.existsSync(gi)) return false; return fs.readFileSync(gi,'utf8').split(/\r?\n/).map(x=>x.trim()).filter(x=>x&&!x.startsWith('#')).some(pattern => { const p=pattern.replace(/^\//,'').replace(/\*/g,'.*'); return new RegExp(`^${p.replace(/[.+?^${}()|[\]\\]/g,'\\$&').replace(/\.\*/g,'.*')}$`).test(path.relative(root,file).replace(/\\/g,'/')); }); }
function filesFor(input) { const absolute=path.resolve(input); if(!fs.existsSync(absolute)) throw new Error(`Path not found: ${input}`); const root=fs.statSync(absolute)&& (fs.statSync(absolute).isDirectory()?absolute:path.dirname(absolute)); const out=[]; function walk(p){const stat=fs.statSync(p); if(stat.isDirectory()){if(EXCLUDED.has(path.basename(p)))return; for(const e of fs.readdirSync(p))walk(path.join(p,e));} else if(EXTENSIONS.has(path.extname(p).toLowerCase())&&!ignoredByGitignore(p,root))out.push(p);} walk(absolute); return out; }
function main() { const o=parse(process.argv.slice(2)); if(o.help){console.log(help());return 0;} if(o.version){console.log(VERSION);return 0;} const files=filesFor(o.path); const issues=[]; const changed=[]; for(const file of files){const source=fs.readFileSync(file,'utf8'); const r=fixSource(source,path.relative(process.cwd(),file)); if(r.changes.length){issues.push(...r.changes); if(o.fix){fs.writeFileSync(file,r.source);changed.push(file);} if(o.diff&&!o.json){for(const c of r.changes) console.log(`line ${c.line}\n- ${c.raw}\n+ ${c.canonical}`);}}} const summary={filesScanned:files.length,filesWithWarnings:new Set(issues.map(x=>x.file)).size,warnings:issues.length,filesChanged:changed.length,issues:issues.map(x=>({file:x.file,line:x.line,column:x.column,from:x.raw,to:x.canonical}))}; if(o.json)console.log(JSON.stringify(summary,null,2)); else if(!o.diff){for(const x of issues)console.log(`${x.file}:${x.line}:${x.column}  ${x.raw} → ${x.canonical}`); console.log(issues.length?`\nFound ${issues.length} canonical warning${issues.length===1?'':'s'} in ${summary.filesWithWarnings} file${summary.filesWithWarnings===1?'':'s'}.${o.fix?' Fixes applied.':' Run with --fix to apply.'}`:`No canonical warnings found in ${files.length} file${files.length===1?'':'s'}.`);} return o.check&&issues.length?1:0; }
try { process.exitCode=main(); } catch (e) { console.error(`twcheck: ${e.message}`); process.exitCode=2; }
